script:
// List View customizations for the Customer doctype
frappe.listview_settings['Customer'] = {
    onload: function (listview) {
        // Adds a bulk action button to send welcome emails to selected customers
        listview.page.add_action_item(__('Send Welcome Email'), function () {
            send_welcome_emails(listview);
        });
    }
};

function send_welcome_emails(listview) {
    // Get names of checked customers in the list view
    let selected = listview.get_checked_items().map(d => d.name);

    if (!selected.length) {
        frappe.msgprint(__('Select at least one Customer first.'));
        return;
    }

    frappe.call({
        method: 'send_customer_welcome_email',
        args: { customers: selected },
        freeze: true,
        freeze_message: __('Sending welcome emails...'),
        callback: function (r) {
            handle_welcome_email_response(r.message || [], listview);
        }
    });
}

function handle_welcome_email_response(results, listview) {
    // Split results by status for separate reporting
    let sent = results.filter(d => d.status === 'sent');
    let skipped = results.filter(d => d.status && d.status.startsWith('skipped'));
    let failed = results.filter(d => d.status === 'failed');

    frappe.msgprint({
        title: __('Welcome Email Results'),
        message: build_result_html(sent, skipped, failed),
        indicator: failed.length ? 'red' : (skipped.length ? 'orange' : 'green')
    });

    // Reset selection and reload the list
    listview.clear_checked_items();
    listview.refresh();
}

function build_result_html(sent, skipped, failed) {
    // Shows customer name with email in brackets when available
    let format_entry = d => d.portal_user ? `${d.customer} (${d.portal_user})` : d.customer;

    let html = `<b>${sent.length} email(s) sent</b>`;

    if (sent.length) {
        html += `<br>${sent.map(format_entry).join(', ')}`;
    }

    if (skipped.length) {
        // Include skip reason (status) alongside each entry
        html += `<br><br><b>${skipped.length} skipped</b>:<br>` +
            skipped.map(d => `${format_entry(d)} - ${d.status}`).join(', ');
    }

    if (failed.length) {
        html += `<br><br><b>${failed.length} failed</b>:<br>${failed.map(format_entry).join(', ')}`;
    }

    return html;
}

// List View customizations for the Supplier doctype
frappe.listview_settings['Supplier'] = {
    onload: function (listview) {
        // Adds a bulk action button to send welcome emails to selected suppliers
        listview.page.add_action_item(__('Send Welcome Email'), function () {
            send_welcome_emails(listview);
        });
    }
};

function send_welcome_emails(listview) {
    // Get names of checked suppliers in the list view
    let selected = listview.get_checked_items().map(d => d.name);

    if (!selected.length) {
        frappe.msgprint(__('Select at least one Supplier first.'));
        return;
    }

    frappe.call({
        method: 'send_supplier_welcome_email',
        args: { suppliers: selected },
        freeze: true,
        freeze_message: __('Sending welcome emails...'),
        callback: function (r) {
            handle_welcome_email_response(r.message || [], listview);
        }
    });
}

function handle_welcome_email_response(results, listview) {
    // Split results by status for separate reporting
    let sent = results.filter(d => d.status === 'sent');
    let skipped = results.filter(d => d.status && d.status.startsWith('skipped'));
    let failed = results.filter(d => d.status === 'failed');

    frappe.msgprint({
        title: __('Welcome Email Results'),
        message: build_result_html(sent, skipped, failed),
        indicator: failed.length ? 'red' : (skipped.length ? 'orange' : 'green')
    });

    // Reset selection and reload the list
    listview.clear_checked_items();
    listview.refresh();
}

function build_result_html(sent, skipped, failed) {
    // Shows supplier name with email in brackets when available
    let format_entry = d => d.portal_user ? `${d.supplier} (${d.portal_user})` : d.supplier;

    let html = `<b>${sent.length} email(s) sent</b>`;

    if (sent.length) {
        html += `<br>${sent.map(format_entry).join(', ')}`;
    }

    if (skipped.length) {
        // Include skip reason (status) alongside each entry
        html += `<br><br><b>${skipped.length} skipped</b>:<br>` +
            skipped.map(d => `${format_entry(d)} - ${d.status}`).join(', ');
    }

    if (failed.length) {
        html += `<br><br><b>${failed.length} failed</b>:<br>${failed.map(format_entry).join(', ')}`;
    }

    return html;
}
